// The checks. Each row will become a named Row plus the three
// assertions about it: that it is here if the table says so, that it is not
// here if the table says ON_NA, and that its value is what the table says.
ON_CLASS_LAYOUT_SIZE_TABLE(ON_CLASS_LAYOUT_SIZE)
ON_CLASS_LAYOUT_OFFSET_TABLE(ON_CLASS_LAYOUT_OFFSET)

// The same rows as data, so the test suite can walk them.
namespace ON_ClassLayout
{
  constexpr Row OpenNurbsClassSizeRows[] =
  {
    ON_CLASS_LAYOUT_SIZE_TABLE(ON_CLASS_LAYOUT_ROW_SIZE)
  };

  constexpr Row OpenNurbsMemberOffsetRows[] =
  {
    ON_CLASS_LAYOUT_OFFSET_TABLE(ON_CLASS_LAYOUT_ROW_OFFSET)
  };

  inline Table OpenNurbsClassSizeTable()
  {
    return Table("OpenNURBS class sizes", OpenNurbsClassSizeRows);
  }

  inline Table OpenNurbsMemberOffsetTable()
  {
    return Table("OpenNURBS member offsets", OpenNurbsMemberOffsetRows);
  }

#if ON_CLASS_LAYOUT_COMPILE_TIME_CHECKS
  static_assert(RowsAreSortedAndUnique(OpenNurbsClassSizeRows),
    "The OpenNURBS class size table is out of alphabetical order, or has two "
    "rows for one class.");
  static_assert(RowsAreSortedAndUnique(OpenNurbsMemberOffsetRows),
    "The OpenNURBS member offset table is out of alphabetical order, or has two "
    "rows for one member.");
  static_assert(AllRowsOk(OpenNurbsClassSizeRows),
    "An OpenNURBS class does not match the class layout table. The per-class "
    "static_assert above names it.");
  static_assert(AllRowsOk(OpenNurbsMemberOffsetRows),
    "An OpenNURBS class member does not match the class layout table. The "
    "per-member static_assert above names it.");
#endif
}

#endif  // ON_CLASS_LAYOUT_RUNTIME_CHECKS

#endif
